import{_ as t,o as s,c as o,ak as i}from"./chunks/framework.sV-XtlWr.js";const g=JSON.parse(`{"title":"Record tests from the editor","description":"Record a Playwright test from VS Code or a JetBrains IDE: a browser your project's own Playwright opens, and each step you take there written at the cursor as you go, with locators verified on the page and calls to your own page objects.","frontmatter":{"title":"Record tests from the editor","description":"Record a Playwright test from VS Code or a JetBrains IDE: a browser your project's own Playwright opens, and each step you take there written at the cursor as you go, with locators verified on the page and calls to your own page objects.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/editor-recording.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/editor-recording.html"}],["meta",{"property":"og:title","content":"Record tests from the editor | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Record a Playwright test from VS Code or a JetBrains IDE: a browser your project's own Playwright opens, and each step you take there written at the cursor as you go, with locators verified on the page and calls to your own page objects."}]]},"headers":[],"relativePath":"features/editor-recording.md","filePath":"features/editor-recording.md","lastUpdated":1791285777000}`),r={name:"features/editor-recording.md"};function a(n,e,d,h,l,c){return s(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="record-tests-from-the-editor" tabindex="-1">Record tests from the editor <a class="header-anchor" href="#record-tests-from-the-editor" aria-label="Permalink to &quot;Record tests from the editor&quot;">​</a></h1><p><strong>Piwi: Record here</strong> opens a browser through your project&#39;s own Playwright and writes what you do there at the cursor, as you do it: steps inside a test, a page object&#39;s method or a helper function, a new test anywhere else in a spec. It works in VS Code (and Cursor, VSCodium) and in the JetBrains IDEs with the <a href="./editors.html#jetbrains-ides">Piwi plugin</a>, and needs no instance, no desktop app and no browser extension.</p><h2 id="start-a-recording" tabindex="-1">Start a recording <a class="header-anchor" href="#start-a-recording" aria-label="Permalink to &quot;Start a recording&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Editor</th><th>Record at the cursor</th><th>Record a new test file</th></tr></thead><tbody><tr><td>VS Code</td><td><strong>Piwi: Record here</strong>, from the command palette or the editor&#39;s context menu</td><td><strong>Piwi: Record a new test file</strong></td></tr><tr><td>JetBrains IDE</td><td><strong>Tools → Piwi → Record Here</strong>, <strong>Alt+Enter</strong> or <strong>Alt+Insert</strong> (Generate), or the editor&#39;s context menu</td><td><strong>File → New → Record a New Test File…</strong></td></tr></tbody></table><p>Before the browser opens, the editor asks for:</p><ol><li><strong>The start page</strong>: a path on the project&#39;s <code>baseURL</code>, or an address; left empty, the browser opens the <code>baseURL</code>.</li><li><strong>The page the steps run on</strong>, when the code around the cursor offers several: <code>page</code>, a fixture such as <code>adminPage</code>, or <code>this.page</code> in a page object. Any other expression can be typed.</li><li><strong>The Playwright project</strong>, when the config has several. The browser gets its <code>use</code> options: <code>baseURL</code>, <code>storageState</code>, the viewport and device, the locale, the extra headers and <code>testIdAttribute</code>.</li></ol><p>The editor offers your last answers again. A new test file is offered next to the file you are in, and the recording writes a whole spec into it.</p><h2 id="while-it-records" tabindex="-1">While it records <a class="header-anchor" href="#while-it-records" aria-label="Permalink to &quot;While it records&quot;">​</a></h2><ul><li><strong>The block</strong> the recording writes is tinted, and written again as each step arrives: a run of steps becomes one call to your own page object or helper once its last step is recorded, and the import that call needs is added at the top of the file.</li><li><strong>The controls</strong>: the step count, <strong>Stop</strong> and <strong>Pause</strong> (<strong>Resume</strong> while paused), above the block in VS Code and in a banner above the editor in a JetBrains IDE, and <strong>Pause</strong>, <strong>Stop</strong> and the checks in the browser&#39;s recording bar. The status bar shows the recording too. While paused, from the editor or the browser, what you do in the browser is not recorded: use it to reach a page or set up data without writing those steps; <strong>Resume</strong> continues from there.</li><li><strong>Checks</strong>: <strong>Check an element</strong> in the browser&#39;s recording bar lets you pick an element and check its text, its value, its accessible name or its state, starting from what it shows now; <strong>Check the address</strong> checks the page&#39;s address. Each is written as an <code>await expect(…)</code> where you added it.</li><li><strong>Typing in the block</strong> pauses the recording. <strong>Resume</strong> writes the block again from the recorded steps, over your edits; <strong>Keep my edits</strong> stops the recording and keeps the code as you changed it.</li><li><strong>Warnings</strong> (a brittle locator, a password read from the environment, a file to upload) are on their lines. They stay after the recording, until the code they describe is edited.</li></ul><h2 id="stop-and-undo" tabindex="-1">Stop and undo <a class="header-anchor" href="#stop-and-undo" aria-label="Permalink to &quot;Stop and undo&quot;">​</a></h2><p><strong>Stop</strong> in the editor or in the browser&#39;s recording bar, or closing the browser, ends the recording, and the code stays. Closing the file ends it too. One <strong>Undo</strong> then removes the whole recording, imports included. In VS Code, a save or an edit of the file during the recording starts a new undo step, so your own changes stay undoable on their own; in a JetBrains IDE, that Undo also takes back the edits you made in the file meanwhile, and Redo brings everything back.</p><h2 id="the-code" tabindex="-1">The code <a class="header-anchor" href="#the-code" aria-label="Permalink to &quot;The code&quot;">​</a></h2><ul><li><strong>Locators</strong> come from the same converter as Piwi Picker&#39;s recordings and <a href="/reference/cli.html#codegen"><code>piwi codegen</code></a>: each is verified to find the element alone on the page, the stable ones first and those your tests already use preferred. A <code>getByTestId</code> uses the attribute your config sets.</li><li><strong>Pages</strong>: an address on the project&#39;s <code>baseURL</code> is written as a path, and the step that leads to another page is followed by a wait for it, except next to a call to your own code, which waits for its pages itself.</li><li><strong>Imports</strong>: a call to your own code, and <code>expect</code> when a step checks something, are imported at the top of the file when it lacks them.</li><li><strong>Your own code</strong>: when the editor is connected to an instance or the <a href="./desktop.html">desktop app</a>, steps that match one of your <a href="./test-functions.html">test functions</a> become a call to it.</li><li><strong>Passwords</strong> are never recorded: the code reads them from an environment variable named after the field, such as <code>process.env.E2E_PASSWORD</code>, including in a call to a page object.</li></ul><h2 id="code-options-in-the-playwright-config" tabindex="-1">Code options in the Playwright config <a class="header-anchor" href="#code-options-in-the-playwright-config" aria-label="Permalink to &quot;Code options in the Playwright config&quot;">​</a></h2><p>How the recorded code looks is set for the whole repository in <code>playwright.config.ts</code>, under the <code>&#39;@piwi&#39;</code> key at the top level, next to <code>testDir</code> and <code>use</code>. Everyone who records in the repository gets the same code, with or without an instance:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { defineConfig } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@playwright/test&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {} </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@piwitests/reporter&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// declares &#39;@piwi&#39; on the config; already there with wrapConfig</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> default</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> defineConfig</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  testDir: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;./tests&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;@piwi&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    codegen: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      testSteps: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;page&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      tags: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;@recorded&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      annotations: [{ type: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;piwi:owner&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, description: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;@shop-team&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Option</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>pageWaits</code></td><td><code>true</code></td><td><code>false</code> leaves out the wait for the next page after a step that leads to it</td></tr><tr><td><code>values</code></td><td><code>&#39;literal&#39;</code></td><td><code>&#39;env&#39;</code> reads every typed value from an environment variable named after its field, not only passwords</td></tr><tr><td><code>envPrefix</code></td><td><code>&#39;E2E_&#39;</code></td><td>What those variables start with, as in <code>E2E_PASSWORD</code>: upper-case letters, digits and underscores</td></tr><tr><td><code>testSteps</code></td><td><code>&#39;none&#39;</code></td><td><code>&#39;page&#39;</code> wraps the steps of each page in <code>await test.step(&#39;/cart&#39;, …)</code>, so the report reads like the scenario; in a test only, not in a page object or a helper</td></tr><tr><td><code>tags</code></td><td>none</td><td>Tags a new test gets</td></tr><tr><td><code>annotations</code></td><td>none</td><td>Annotations a new test gets, <code>{ type, description? }</code></td></tr></tbody></table><p>The editor reads the section through your project&#39;s own Playwright, which hands the top-level keys starting with <code>@</code> to reporters as they are written, so it applies to the recordings started after the config is saved. <strong>Send to editor</strong> from Piwi Picker follows it too. An unknown option or a value of the wrong kind is left out, and the recording says so when it starts.</p><h2 id="send-from-piwi-picker" tabindex="-1">Send from Piwi Picker <a class="header-anchor" href="#send-from-piwi-picker" aria-label="Permalink to &quot;Send from Piwi Picker&quot;">​</a></h2><p>A locator picked with the <a href="./extension.html">Piwi Picker</a> browser extension in your everyday browser, or a flow it recorded, lands at the editor&#39;s cursor too:</p><ol><li>In the editor, run <strong>Piwi: Pair with Piwi Picker</strong> (<strong>Tools → Piwi → Pair with Piwi Picker</strong> in a JetBrains IDE). It copies a pairing address, <code>http://127.0.0.1:&lt;port&gt;/…#&lt;token&gt;</code>.</li><li>In Piwi Picker&#39;s settings, paste it under <strong>Send to editor</strong> and click <strong>Pair</strong>; the browser asks once for access to that local address.</li><li>A picked locator&#39;s row and the recording review then show <strong>Send to editor</strong>. A locator is inserted in the copy form you chose; a recording is rendered as the body of a test, like <a href="/reference/cli.html#codegen"><code>piwi codegen --body</code></a>.</li></ol><p>The editor listens on the loopback interface only, and accepts a request only with the token. With several VS Code windows open, the one that paired receives.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>The browser is the one your tests use, installed by Playwright (<code>npx playwright install chromium</code>).</li><li>The recording does not start your <code>webServer</code>: start the application first.</li><li>It records the top-level page: clicks inside an iframe, and steps in a popup or a new tab, are not recorded yet.</li><li>A file takes one recording at a time.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./editors.html">Editor extensions</a>: everything else the editor shows from your suite.</li><li><a href="./extension.html">Piwi Picker</a>: records in your everyday browser, for a bug report or a steps file.</li><li><a href="./test-functions.html">Test functions</a>: the page objects and helpers a recording calls.</li></ul>`,26)])])}const k=t(r,[["render",a]]);export{g as __pageData,k as default};
